    purpose:'首をやさしく回す。',
    how:["イスに浅く腰かけ、足の裏を床につけ、背すじを軽く伸ばします。両手は太ももの上に置き、最後まで手を太ももから離しません（こうすると肩が動きません）。","あごを胸に近づけて頭を下に向けます。ここが円のスタート地点です。","1周に6秒くらいかけて、頭を右の肩の方へ→後ろ→左の肩の方へ→下（スタート）へと、自分で支えながらゆっくり動かして円を描きます。力を抜いて頭を落とすのではありません。","後ろを通るときは、あごを軽く引いたまま通ります。あごが天井を向くまでは倒しません。これを右回りに5回。","同じように、反対まわり（頭を左の肩の方から回す向き）を5回。痛みが出る位置があれば、そこを通らないように円を小さくします。めまいや痛みが出たら中止してください。","頭を正面に戻して終わります。首が軽くなる感じがなくても失敗ではありません。"],
