    how:["マットに仰向けになり、両ひざを立てます。足の間はこぶし2つ分、かかとはお尻から握りこぶし1つ分あけ、両手は体の横、目線は天井へ。","お腹を、せき払いをするときのように軽く硬くします。息は止めません。","息を吐きながらお尻に力を入れ、3秒かけてお尻を床から浮かせ、続けて腰も浮かせます。お尻がキュッと硬くなればOKです。","腰にギュッとつまる感じや痛みが出たら、それが上げすぎの合図です。すぐに数cm下げ、つまる感じが消えた高さで止めます。","息を吸いながら3秒かけて、腰→お尻の順に床へ下ろします。","これを12回くり返します。"],
