    cues:{"do":"腰の下に入れた手の甲の圧が変わらないように、脚はゆっくり上げ下げしましょう。","dont":"反動で脚を振り上げません。腰の下のすきまが急に広がるほど、腰をそらしません。"}, easyOption:"各10回がきつければ、脚を上げる高さを半分（ひざが床から30cmくらい）にして行います。",
