    cues:{"do":"背中とお尻を壁につけたまま、ひざだけを開きましょう。お尻の横が熱くならなくても、壁が離れていなければOKです。","dont":"背中やお尻が壁から離れるほど、ひざを大きく開きません。"}, easyOption:"各15回がきつければ、8回ずつ2回に分け、間に30秒休んでから行います。",
