    purpose:'座位で足首を大きく回す。',
    how:["イスか床に座り、右の足首を左の太ももの上にのせます。","左手で右の足首（くるぶしのすぐ上）をしっかり押さえ、右手で右足のつま先を持ちます。","つま先で大きな円を描くように、つま先を小指のほうへ回していきます（これが外回りです）。1周4秒くらいかけて5周まわします。","続けて、つま先を親指のほうへ回します（これが内回りです）。同じく1周4秒で5周。押さえている左手が動かなければ、足首だけが動いている合図です。","左右を入れかえ、左足も外回り・内回り各5周まわします。"],
    cues:{"do":"つま先で、できるだけ大きな円を4秒かけてていねいに描きましょう。足首を押さえている手が動かないようにします。","dont":"力を入れて速くまわしません。痛む向きは円を小さくします。"}, easyOption:"足首を太ももの上にのせられない場合は、イスに座って足を床につけ、かかとを床につけたまま、つま先だけで同じように円を描きます。",
