    illustration: SVG2.forwardFold,
    purpose:'長座で片足を引き寄せ伸ばす。',
    how:["マットに座り、右脚を前へまっすぐ伸ばします。左ひざを曲げ、左の足の裏を右の内ももにつけます。左ひざが床から浮いたままでもOKです（気になれば左ひざの下にクッションを入れます）。視線は前へ。","タオルを右足の裏（指の付け根のあたり）にかけ、両端を左右の手で持ちます。手でつま先に届く人は、直接つま先を持ってもかまいません。","頭のてっぺんを天井へ引き上げるように背すじを伸ばし、肩は上げずに、タオルを3秒かけて手前（自分のほう）に引きます。右のつま先が自分のほうへ倒れてくればOKです。","右ひざは少し曲がってもかまいません（曲がっていてもふくらはぎは伸びます）。痛みが出る一歩手前で止め、30秒キープします。","ゆっくり戻し、左右を入れかえて同じように30秒行います。"],
    cues:{"do":"背中を丸めず、頭のてっぺんを天井へ引き上げたまま座り、タオルは3秒かけてじわっと引きましょう。","dont":"痛みが出るほど強く引っ張りません。反動をつけて何度も引きません。"}, easyOption:"床に座るのがつらい場合は、イスに座って片脚を前へ伸ばし、かかとを床につけたまま、タオルをつま先にかけて同じように手前へ引きます。",
    why:'ふくらはぎの柔軟性。'
