    how:["椅子に浅く（お尻の半分だけが座面にのる位置）腰かけ、足の裏を床につけ、肩の力を抜きます。視線は前。","右手を、おへそから指3本分下（ズボンのゴムが当たるあたり）のお腹に当てます。左手はももの上に置きます。","口から細く息を吐き切ります。吐き切るとお腹はへこみます。そこからもう一段、当てた右手のひらがお腹から遠ざかるように、お腹を2〜3cm奥へ引き込みます。これが「おへそを背中側へ引き入れる」ことです。","引き込んだ形を保ったまま、鼻から小さく吸って吐くをくり返し、5秒続けます。吸ったときに右手が前へ押し返されなければ、保てているサインです。","お腹の力をゆるめて3秒休み、これを10回くり返します。"],
    cues:{"do":"お腹に当てた手が前へ押し出されないように、引き込んだまま小さく呼吸を続ける。","dont":"肩をすくめたり、背中を丸めたりしない。息を止めない。"},
    why:'インナーマッスル活性化。'
