    cues:{"do":"お尻に当てた手の下がかたく縮むのを確かめながら力を入れ、その間も自然に呼吸を続ける。","dont":"おへそに当てた手が前へ押し出されるほど、おへそを前へ突き出さない。"},
    why:'お尻の意識付け。'
