    targetProblems:['roundedShoulders','thoracicKyphosis'],
    category:'training', technique:'strength', bodyPart:'arm', intensity:2,
    equipment:'マット', position:'kneeling', duration:'8回 × 2セット',
    illustration: SVG2.pushup,
    purpose:'膝つきでやさしくプッシュアップ。',
    how:["マットで四つ這いになり、ひざ・すね・足の甲を床につけます（足首は組みません）。","手のひらを、肩の真下から手のひら1つ分前・手のひら1つ分外側の床に置きます。指先は前へ。","両ひざをこぶし2つ分うしろへずらし、続けてお尻を前へ下げて、頭・お尻・ひざが1本のまっすぐな線になる位置で止めます（お尻がひざの真上に高くある「くの字」ではありません）。視線は手の少し前の床へ。","息を吸いながら3秒かけてひじを曲げ、胸を床へ下ろします。胸と床のすき間がこぶし1つ分になったところで止めます。この間、お尻の高さは3で作ったまっすぐな線のまま変えません。","息を吐きながら手で床を押し、3秒かけて元の位置まで戻します。","8回くり返したら60秒休み、もう1セット行います。途中で押し戻せなくなったら、ひざをついたまま体を床に下ろして休みます。痛みが出たら中止します。"],
    cues:{"do":"胸がいちばん先に床へ近づくように下ろす。","dont":"お尻を高く突き上げない。お腹やお尻が先に床につくのは、まっすぐが崩れたサイン。"}, easyOption:"腕の運動をしたことがなければ、はじめから壁で行ってかまいません。壁から一歩（足の長さ2つ分）離れて立ち、両手を肩の高さ・肩幅より手のひら1つ分ずつ外側の壁につきます。3秒かけてひじを曲げて胸を壁からこぶし1つ分の所まで近づけ、3秒かけて押し戻します。8回くり返したら60秒休み、もう1セット行います。",
    why:'上半身の基本筋力。'
