    equipment:'なし', position:'standing', duration:'各30秒',
    illustration: SVG2.singleLegBalance,
    purpose:'片脚立ちでバランス。',
    how:["壁か椅子の背を体の横30cmほどのところに置き、足をそろえてまっすぐ立ちます。視線は前。","支える右のひざは、ピンと突っ張らせず、1〜2cmだけ曲げておきます（いつでもさらに曲げられる状態にしておくことです）。","左のひざを曲げて、左足を床からこぶし1つ分（約10cm）浮かせます。","上体はまっすぐのまま、2〜3m先の一点を見つめて30秒キープします。足の裏の、親指の付け根・小指の付け根・かかとの3点で床を押し続けます。","ふらついて壁や椅子に触れても、やり直しにはなりません。触れて立て直し、そのまま30秒まで続けます。","ゆっくり左足を下ろし、反対の脚でも30秒行います。"],
    cues:{"do":"2〜3m先の一点をじっと見つめ、足の裏の3点（親指の付け根・小指の付け根・かかと）で床を押し続ける。3点のどれかが浮いたら、体が傾いたサイン。","dont":"支える脚のひざをピンと突っ張らない（1〜2cmだけ曲げておく）。"}, easyOption:"30秒立っていられなければ、指先を壁か椅子の背に触れたまま、10秒×3回に分けて行う。",
