    how:["マットに四つん這いになります。手のひらは肩の真下、ひざはお尻の真下につき、手の指は大きく開いて床を押します。","背中は床と平行のテーブルのようにまっすぐ、目線は手のひらの少し前の床へ向けます。","3秒かけて息を吐きながら、おへそを覗き込むように背中を天井へ丸め、目線をおへそへ移します。","3秒かけて息を吸いながら、みぞおち（胸の真ん中の骨をなぞって下りた、やわらかいくぼみ）を床へ近づけ、胸の中心を前に置いた手のほうへ送り出すように背中を反らせ、目線を斜め前上へ移します。","この丸める・反らすを10回くり返します。ひざ・手首・首・腰に痛みが出たら中止します。"],
