    how:["マットで正座になります。両ひざの間はこぶし2つ分（約15cm）あけ、足の甲は床につけ、左右の足の親指を軽く重ねます。","両手を太ももの上に置き、視線はまっすぐ前へ向けます。","息を吐きながら上半身を前に倒し、両手を前方の床へできるだけ遠く滑らせ、額を床につけます。","額が床に届かなければ、重ねた両手の甲か、顔の真下に置いたクッション（額と床のすき間がちょうど埋まる厚さ）に額をのせます。","お尻をかかとに預けたまま、鼻から吸って口から吐く深い呼吸を続けて1分キープします。","両手で床を押してゆっくり起き上がります。ひざや足首に痛み・しびれが出たら、我慢せずすぐやめます。"],
    cues:{"do":"お尻はかかとに預けたまま、あご・首・肩の力を全部抜いて体を床に沈める。","dont":"肩を耳に近づけてすくめない。ひざや足首のしびれ・痛みを我慢して続けない。"}, easyOption:"正座がつらければ、ふくらはぎと太ももの間にたたんだ座布団をはさんで高さを作り、同じ姿勢で1分行う。",
