    purpose:'立位で片膝を胸へ。',
    how:["壁の横にまっすぐ立ち、足の間はこぶし2つ分あける。壁側の手を肩の高さで壁につけて支える。視線はまっすぐ前へ。","壁と反対側のひざを曲げて持ち上げ、空いているほうの手で太ももの裏側（ひざの裏のすぐ上）を下から抱える。もう一方の手は壁につけたまま。","立っている脚のひざは伸ばしたまま、抱えた太ももを3秒かけて胸のほうへ引き寄せる。太ももがお腹に軽く触れたら止める。それ以上は引かない。痛みが出たら弱める。","その位置で「いち、に…」と1秒に1つ、20まで数える。ふらついて足が床についたら、数は止めずにすぐ抱え直す。","足を下ろし、体の向きを変えて、反対の脚も同じように20数える。"],
    cues:{"do":"立っている脚のひざは伸ばしたまま、背すじを上へ伸ばして数え終わるまで保つ。","dont":"背中を丸めて頭を前へ出さない。上体を後ろへ倒してごまかさない。ひざのお皿を強く押さえない。"}, easyOption:"片脚立ちがつらければ、イスに深く座り、背もたれに背中をつけたまま行う。片ひざを両手で抱え、太ももがお腹に軽く触れるまで引き寄せて20数える。左右各1回。",
