    purpose:'仰向けで片足を伸ばし戻す。',
    how:["マットに仰向けになり、両ひざを立てて足の裏を床につける。かかとが滑るよう、靴下をはくか、かかとの下にタオルを1枚敷く。目線は天井。","右手の甲を床につけ、手のひらを上にして腰と床のすき間へ差し込む。左手は体の横に置く。","口から息を細く吐きながらお腹を軽くへこませ、腰で右手の甲を押さえる。差し込んだ右手の指を動かそうとしても動かせないくらい押さえられていればOK。","息を吐きながら、右のかかとを床（タオル）に滑らせ、3秒かけて右脚をまっすぐ前へ伸ばす。途中で右手の指が楽に動くようになったら腰が浮いたしるし。その手前で止める。","息を吸いながら3秒かけてかかとを滑らせ、ひざを立てた元の位置へ戻す。右10回、続けて左脚も同じように10回（手はそのまま）。腰に痛みが出たら中止する。"],
    cues:{"do":"脚を伸ばす間ずっと、腰の下に入れた手の指が動かせないままかを確かめる。","dont":"手がゆるんで指が動くところ（腰が浮くところ）まで脚を伸ばさない。脚は床まで届かなくてよい。息を止めない。"},
    why:'コアの基本制御。'
