    how:["マットに仰向けになり、両ひざを立てて足の裏を床につける。目線は天井。","左手の甲を床につけ、手のひらを上にして腰と床のすき間へ差し込む。右腕はまっすぐ天井へ伸ばす。","口から息を細く吐きながらお腹を軽くへこませ、腰で左手の甲を押さえる。差し込んだ左手の指を動かそうとしても動かせないくらい押さえられていればOK。","息を吐きながら、右腕を3秒かけて頭の上（耳の横）の床のほうへ下ろす。左手の指が楽に動くようになったら腰が浮いたしるし。その手前で止める。床に届かなくてよい。肩が突っ張ったらそこで止める。","息を吸いながら3秒かけて天井へ戻す。右腕10回。手を入れ替えて左腕も10回。肩や腰に痛みが出たら中止する。"],
