    illustration: SVG2.bridge,
    purpose:'ブリッジでキープ。',
    how:["マットに仰向けになり、両ひざを立てて足の裏を床につける。足の間はこぶし2つ分のすき間をあける。腕は体の横、手のひらは床、目線は天井。","持ち上げる前に、トイレを我慢するようにお尻の穴を締める。お尻全体が硬くなる。この締めを最後までゆるめない。","お尻を締めたまま足の裏で床を押し、3秒かけて腰を持ち上げる。かかとが浮いたら上げすぎ。かかとが床についたままでいられる高さで止める。","自然に呼吸しながら、「いち、に…」と1秒に1つ、30まで数える。腰の後ろに詰まった感じや苦しさが出たら、こぶし1個分（約10cm）下げる。数は止めずに続ける。","3秒かけてゆっくり下ろす。30数えて休み、もう1回。計2回。腰やひざに痛みが出たら中止する。"],
    cues:{"do":"持ち上げる前にお尻の穴を締め、下ろし終わるまでゆるめない。","dont":"お尻を締めずに腰から先に持ち上げない。かかとが浮くほど高く上げない。"}, easyOption:"30数えるのがきつければ、10数えて下ろすを2回から始め、慣れたら数を増やす。",
    why:'臀筋持久力UP。'
