    illustration: SVG2.birdDog,
    purpose:'四つん這いで片腕を前に。',
    how:["マットに四つん這いになる。ひざが痛ければ、たたんだバスタオルをひざの下に敷く。","手は肩の真下、ひざはお尻の真下につく。頭からお尻までを一本の板のようにまっすぐ保ち、目線は手の少し前の床。","口から息を細く吐いてお腹を軽くへこませ、その硬さを保つ。そのあとは息を止めず、自然に呼吸を続ける。","右腕を3秒かけて前へまっすぐ伸ばし、指先で前の壁を押すつもりで伸ばす。腰の後ろに詰まった感じが出たら上げすぎなので、指先を少し下げる。","3秒かけて床へ戻す。左腕も同じように行う。左右10回ずつ。手首・ひざ・腰に痛みが出たら中止する。"],
    cues:{"do":"腕を上げている間も、頭からお尻までの板の形を変えず、床についた手とひざが浮かないまま保つ。","dont":"背中をそらせてお腹を床へ落とさない。体が傾いて手やひざが床から浮きそうになったら、腕を下ろしてやり直す。"}, easyOption:"ひざが痛い・きついときは、ひざの下にたたんだバスタオルを敷き、腕を前へ伸ばすのは指先が床のすぐ上（床から手のひら1つ分＝約10cm）を通る高さまでにして、左右5回ずつに減らす。",
