    illustration: SVG2.bridge,
    purpose:'仰向けで両膝を内側に絞る。',
    how:["マットに仰向けで寝て、両ひざを立て、足の裏を床につける。目線は天井。","左右のひざと、ももの内側どうしをぴったり合わせる。クッションなどの道具ははさまない。","両手の指先を、ひざの少し上のももの内側のふちに、脚の上から回して軽く当てる。手はももの間にはさまない。","口から息を細く吐きながらお腹をへこませ、左右のひざを内側へ押し合う。力は全力の半分くらい（押しながら普通に声が出せる程度）。指先の下のももの内側が硬くなればOK。","声に出して「いち、に…」と1秒に1つ、10まで数えて力を抜く。ひと呼吸おいて、これを5回くり返す。ひざや股に痛みが出たら中止する。"],
    cues:{"do":"押し合っている間ずっと、指先の下のももの内側が硬いままかを手で確かめ続ける。","dont":"力むあまり息を止めない。数を声に出して数えれば息は止まらない。"},
    why:'内転筋・骨盤底の活性化。'
