    cues:{"do":"お腹の手→わき腹の手→胸、の順に動くよう、当てた手を押し返すつもりで吸う。","dont":"肩を持ち上げて力まない。手がうまく動かなくても息を止めない。"}, easyOption:"10数えるのがきつければ、5数えて力を抜くを5回にする（押す強さは同じ、全力の半分くらい）。",
