    illustration: SVG2.squatHold,
    purpose:'スクワット下位で姿勢を保つ。',
    how:["イスを1脚、座面が自分の真後ろに来るように置く。ふくらはぎの裏が座面の前ふちに軽く触れる位置に、足は肩幅（足の間にこぶし2つ分のすき間）に開いて立つ。","両手を前へまっすぐ、肩の高さに伸ばす。これは体が後ろへ倒れないようにするおもり。目線は正面。","お尻を後ろのイスへ引きながら3秒かけて沈み、お尻が座面からこぶし1つ分（約10cm）浮いた高さで止まる。確かめ方：そこでお尻を少し後ろへ動かすと座面に軽く触れる。","呼吸を止めずに30秒止まる。キープ中にお尻が座面に触れたら、高さが下がってきたサイン。少し上げ直す。上げ直せなければ、そのままイスに座ってよい。","ゆっくり立ち上がる。1分休んで、計3セット。ひざや腰に痛みが出たら中止する。"],
    cues:{"do":"足の指の付け根とかかとの両方で床を踏み、ひざは左右のつま先が向いている方向へ向けたまま保つ。キープ中も声が出せるくらい呼吸を続ける。","dont":"太ももが震えて姿勢が崩れたまま続けない。崩れたら後ろのイスに座って休む。"}, easyOption:"30秒がきつければ、1セット10秒にして3セット行う（セットの間は1分休む）。止まる高さは本文と同じ、座面からこぶし1つ分（約10cm）浮いた高さ。慣れたら15秒、20秒と伸ばす。",
    why:'下半身筋持久力を集中的に向上。'
