    targetProblems:['lateralAsymmetry','kneeValgus','general'],
    category:'strength', technique:'strength', bodyPart:'legs', intensity:2,
    equipment:'なし', position:'standing', duration:'各10回 × 3セット',
    illustration: SVG2.sideLunge,
    purpose:'横方向に大きく踏み出してしゃがむ。',
    how:["イスの背もたれを体の前に置き、両手を軽く添える。","足の間に自分の足の裏2つ分（約50cm）のすき間をあけて立つ。つま先は両方とも正面へ。目線は正面。","曲げる側のひざを3秒かけて曲げ、その足へ体重を移す。お尻は真下ではなく、自分の後ろへこぶし2つ分（約20cm）引く。反対の脚は伸ばしたまま。","反対側の脚の内ももが軽く突っぱるのを感じたら、そこで止める。それ以上は沈まない。","曲げた足で床を押し、2秒かけて中央に戻る。左右各10回を3セット。セットの間は1分休む。","内ももやひざに痛みが出たら中止する。"],
    cues:{"do":"曲げる側の足の裏全体を床につけたまま沈む。足の外側が浮いたら、ひざが内側へ入っているサイン。いったん戻してやり直す。","dont":"内ももが痛くなるところまで沈まない。軽い突っぱりを感じた手前で止める。"}, easyOption:"きつい・ふらつく場合は、内ももが突っぱり始める手前までの浅い深さにとどめ、左右各4回×3セットに減らす（合計24回、セットの間は1分休む）。足の開きは本文と同じ約50cmのままにする。慣れたら回数を増やす。",
    why:'内転筋・中臀筋を同時に鍛え骨盤の左右差改善。'
