    purpose:'前後開脚位置で深く沈む。',
    how:["イスの背もたれを体の正面に置き、両手を軽くのせます。目線は正面にします。","片足を、自分の足の裏2つ分（約50cm）前に出します。後ろの足はかかとを浮かせ、つま先だけを床につけます。","後ろの足のひざの真下あたりに、たたんだ座布団を2枚重ね（厚さ20cmほど）にして置きます。","イスに添えた両手で体を支えながら、3秒かけて浅く沈みます。後ろのひざが座布団に触れたら止めます。前のひざが前の足のつま先より前に出ない範囲でとどめます。","イスに添えた手と前の足のかかとで床を押し、2秒かけて立ちます。片足10回、足を替えて10回、これを2セット。","前ひざやひざに痛みが出たら、沈むのを浅くするか中止します。"],
    cues:{"do":"前の足の裏全体を床につけたまま沈む。足の内側や外側が浮いたら、ひざが横へずれているサイン。いったん立ってやり直す。","dont":"前の足のかかとを浮かせない。かかとが浮いたら、沈むのを浅くする。"}, easyOption:'きつければ、イスの背もたれを両手でしっかり握り、腕にも体重を預けて支えます。座布団を3枚重ね（厚さ30cmほど）にして、後ろのひざが触れたらすぐ止め、沈む深さをさらに浅くします。回数は片足3回ずつ、足を替えて2セット（合計12回）に減らします。前後にふらつく間は、両手をイスから離さないでください。',
    why:'下半身の単側強化で歩行能力・姿勢改善。'
