    purpose:'空気椅子を45秒キープ(壁を背に立てなくてもOK)。',
    how:["イスを1脚、座面が自分の真後ろに来るように置きます。座面にたたんだバスタオルか座布団を1枚のせておくと、お尻が触れる位置が分かりやすくなります。ふくらはぎの裏が座面の前ふちに軽く触れる位置に、足は肩幅（足の間にこぶし2つ分のすき間）に開いて立ちます。このイスが、壁の代わりに沈む深さの目印になります。","両手は胸の前で組み、目線は正面にします。","お尻を後ろのイスへ引きながら3秒かけて沈み、お尻が座面（のせたタオル）に軽く当たったら、そこで止めます。当たった感触が、これ以上沈まない合図です。体重は預けません。","そのまま呼吸を続け、声に出して数えながら45秒キープします。座面にお尻の体重を預けてしまったら、その回はそこで終わりにしてよいです。","ゆっくり立ち上がります。1分休んで、計3セット。ひざに痛みが出たら中止します。"],
    cues:{"do":"45秒の間ずっと、声に出して数を数え続ける。声が出せていれば息は止まっていない。","dont":"お尻の体重をイスに預けない。座面に触れているだけにする。"}, easyOption:'45秒がきつければ、1セット15秒にして3セット行います（セットの間は1分休む）。止める高さは本文と同じで、お尻が座面（のせたタオル）に軽く触れたところです。慣れたら20秒、30秒と伸ばします。',
    why:'大腿四頭筋・臀筋の持久力を高め基礎代謝アップ。'
