    cues:{"do":"立つときはかかとで床を押す。かかとが床から浮かないようにする。","dont":"あごを胸につけて下を向かない。目線は前の壁へ向けたまま。ひざの前が痛むときは、お尻を後ろへ引けていないので、もっと後ろへ引く。"}, easyOption:"15回続けてがきつければ、5回ごとにいったんイスに深く座って10秒休み、それを3回くり返して合計15回にする（これで1セット）。セットは1セットだけにして、慣れたら2セット、3セットと増やす。休むとき以外は、本文どおり座面にお尻を軽く触れさせるだけにする。",
    why:'日常動作直結の下肢強化で結果が出やすい。'
