    cues:{"do":"上げている間ずっと、足の親指の付け根が床を押しているのを感じる。感じられないときは、いったん下ろして体重をそこへ移してから上げ直す。","dont":"反動をつけて跳ねない。一番上で1秒止まれない速さは速すぎ。"}, easyOption:"20回続けてがきつければ、1セット8回に減らして3セット行う（合計24回）。セットの間は30秒、足首を回して休む。慣れたら1セット12回、15回と増やす。",
