    targetProblems:['lateralAsymmetry','anteriorPelvicTilt'],
    category:'strength', technique:'strength', bodyPart:'glutes', intensity:2,
    equipment:'マット', position:'supine', duration:'各8回 × 2セット',
    illustration: SVG2.bridge,
    purpose:'片足を浮かせてブリッジ。',
    how:["マットに仰向けになり、両ひざを立てる。足の間はこぶし2つ分、目線は天井。","両手を左右の腰の骨（体の横、おへその高さより少し下で、手を当てるとかたく出っぱっている所）に当てる。この手は終わりまで離さない。","片方の足を床から手のひら1枚分（10cmほど）浮かせ、ひざは伸ばせるところまで伸ばす。伸びきらなくてよい。","床についた足のかかとで床を押し、3秒かけてお尻を持ち上げる。腰につっぱる感じが出る手前で止める。","両手に当たる左右の腰の高さがそろっているか触って確かめ、3秒かけてお尻を下ろす。8回行い、反対の足も同様に。左右2セット。","腰やもも裏に痛みが出たら中止する。"],
    cues:{"do":"両手を腰の骨に当てたまま、左右の手の高さをそろえて上げ下げする。","dont":"浮かせた側の手が下がったまま（お尻が傾いたまま）続けない。下がったらお尻を床に下ろしてやり直す。"}, easyOption:"ひざを伸ばすと上がらない場合は、浮かせる側のひざを曲げたまま足の裏だけを床から10cm浮かせ、各5回×2セットに減らす。それでもお尻が上がらなければ、両足の裏を床につけたまま同じお尻上げを8回×2セット行う。",
    why:'左右差是正と単脚臀筋強化。'
