    targetProblems:['anteriorPelvicTilt','general'],
    category:'core', technique:'core', bodyPart:'glutes', intensity:2,
    equipment:'マット', position:'supine', duration:'各10回 × 2セット',
    illustration: SVG2.bridge,
    purpose:'ブリッジ姿勢のまま脚を交互に持ち上げる。',
    how:["マットに仰向けになり、両ひざを立てて足の裏を床につけます。足の間はこぶし2つ分、目線は天井です。","お尻の左右を内側へ寄せ合う力で、3秒かけて腰を持ち上げます。腰につっぱる感じが出る手前で止めます。","両手を左右の腰の骨（体の横、おへその高さより少し下の、手を当てるとかたく出っぱっている所）に当て、左右の手が同じ高さにあるのを触って確かめます。","お尻の力をゆるめないまま、片方の足を床から少しだけ（5〜10cmほど）浮かせます。ひざは曲げたままで、高く上げようとしません。浮かせるのは、手に当たる腰の高さが下がらない範囲までです。","3秒かけて足を床に戻し、反対の足を同じように浮かせます。左右各10回を2セット。","終わったらお尻を3秒かけて床へ下ろします。腰に痛みが出たら中止します。"],
    cues:{"do":"腰の骨に当てた両手で、腰の高さが変わっていないかを触って確かめながら足を動かす。","dont":"足を浮かせた側の腰を落とさない。手に当たる高さが下がったら、そこで足を床に戻す。"}, easyOption:'腰が落ちてしまう・最後まで続かない場合は、足を浮かせる代わりに、片足のかかとだけを床から3〜5cm浮かせ（つま先は床につけたまま）3秒キープします。各5回×1セットに減らします。',
    why:'臀筋・体幹・腸腰筋を一度に鍛えるオールインワン。'
