    how:["マットで四つん這いになる。手は肩の真下、ひざは腰の真下。両手の間の床に一点を決めて、そこをずっと見つめる。","お腹は、軽く咳をしたときの硬さにしておく（息は止めない）。","右のひざを床から2〜3cm浮かせる。ひざは四つん這いのときの曲がった角度のままで、足の裏は天井のほうを向く。","曲げたままの右の太ももを、3秒かけて後ろ上へ持ち上げる。上げるのは太ももが床と平行になるところまで。そこまで上がらなくてよい。","腰の前側がグッと突っ張ったら上げすぎ。少し下げる。","3秒かけてひざを元の位置へ戻す。15回行い、反対の脚も15回。ここまでで1セット、合計2セット。腰に痛みが出たら中止する。"],
    cues:{"do":"3秒かけて上げ、腰の前側が突っ張らない高さで止める。","dont":"反動で振り上げない。見つめている床の一点がずれるほど体を傾けない。"}, easyOption:"手首やひざが痛い、または最後まで続かない場合は、手のかわりにひじを床につき（ひじは肩の真下）、ひざの下にたたんだタオルを敷いて、各8回×2セットに減らして行う。",
