    illustration: SVG2.clamShell,
    purpose:'横向き膝曲げで上の膝だけを開く。',
    how:["壁ぎわのマットに横向きに寝て、背中とお尻を壁につけます。","イスに座ったときの脚の形（ひざを曲げて太ももを体の前へ出した形）のまま横に倒れた形にし、両ひざとかかとを上下にそろえて重ねます。","下の腕を枕にして頭を乗せ、上の手は胸の前の床につきます。目線は正面（ひざを確かめるときは、頭は動かさず目だけで見下ろしてよいです）。","両方のかかとをぴったり合わせたまま、3秒かけて上側のひざだけを、貝の口が開くように天井のほうへ開きます。開くのは、上のひざが下のひざからこぶし1つ分（10cmほど）離れるところまでです。","3秒かけてひざを閉じて戻します。20回行い、向きを変えて（また背中とお尻を壁につけて）20回。ここまでで1セット、合計2セット。","痛みが出たら中止します。"],
    cues:{"do":"背中とお尻を壁につけたまま、3秒かけてひざだけを開く。かかとは最後まで離さない。","dont":"体を壁へ押しつけて、こぶし1つ分より大きく開こうとしない。反動で開かない。"},
    why:'股関節外旋筋を強化し膝の方向を整える。'
