    purpose:'床上でヒップスラスト動作。',
    how:["仰向けに寝て両ひざを立てる。足の間はこぶし2つ分あける。","両腕を体の横に伸ばし、指先がかかとに軽く触れる位置にかかとを置く。手のひらは床、目線は天井。","肛門をそっと閉じるように軽く力を入れる。すると左右のお尻の肉が中心へ寄る感じがする。その力を保ったまま、３秒かけて腰を床から持ち上げる。","上げるのは、腰の前側がグッと突っ張る手前まで。突っ張った、または腰が痛いと感じたら上げすぎなので、少し下げる。","一番高い位置で３秒キープ。両手のひらは床につけたまま、息は止めない。","３秒かけて床へ下ろす。15回を3セット。セットの間は30秒休む。腰に痛みが出たら中止する。"],
