    illustration: SVG2.boatPose,
    purpose:'座位で足を浮かせV字形をキープ。',
    how:["マットに座り、両脚を前へまっすぐ伸ばす。両手はお尻から手のひら1枚ぶん（約20cm）後ろの床に置き、指先はお尻のほうへ向ける。この手は最後まで床につけたままでよい。目線は正面。","上体を後ろへ倒していき、ひじが伸びきって腕が突っ張るところで止める。","両ひざを曲げて足を床から握りこぶし2個ぶん（約20cm）浮かせ、つま先は天井へ向ける。","頭のてっぺんを斜め後ろの天井へ引き上げるつもりで、30秒キープ。呼吸は止めない。足が床についたら、そこで1セット終了にしてよい。","足を床に下ろし、1分休んでもう1セット。腰に痛みが出たら中止する。"],
    cues:{"do":"手のひらで床を押し、腕を突っ張ったまま30秒保つ。","dont":"背中を丸めて、あごが胸につくほど頭を落とさない。"}, easyOption:"30秒がつらければ、片脚ずつにする。右足だけを約20cm浮かせて5秒キープ→下ろす、次に左足だけを5秒キープ→下ろす。左右3回ずつ（合計30秒ぶん）。浮かせないほうの足の裏は床につけたまま。1分休んで2セット。",
    why:'腹筋・腸腰筋を統合的に強化。'
