    cues:{"do":"「1、2、3」と声に出して数えて下げ、「1」で戻す。この速さを守る。","dont":"胸より先にお腹や太ももが床に触れるほど、体を落とさない。"}, easyOption:"腕がつらければ壁で行う。壁から大またで一歩（約60cm）離れて立ち、両手を肩の高さで、肩幅より左右にこぶし1個ぶん外側の壁につく。かかとを床につけたまま3秒かけてひじを曲げ、胸が壁に軽く触れたら1秒で押し戻す。10回×3セット（間に1分休む）。",
