    cues:{"do":"胸がマットに触れそうで触れない高さを保ったまま、呼吸を続ける。","dont":"胸より先にお腹や太ももが床に触れるほど、体を落とさない。"}, easyOption:"床で数秒も止まれなければ壁で行う。壁から大またで一歩（約60cm）離れて立ち、両手を肩の高さ・肩幅の壁につく。かかとを床につけたままひじを曲げ、胸と壁のすき間がこぶし1個ぶんになる高さで止めて30秒キープ。呼吸は止めない。1分休んで2セット。",
