    cues:{"do":"お尻が床に触れる手前で折り返す。触れたら下げすぎ。","dont":"肩を耳へ近づけて首を縮めない。"}, easyOption:"腕だけでお尻が浮かなければ、両ひざを立て、かかとをお尻から手のひら2枚ぶん（約40cm）前の床に置く。足の力も使ってお尻を約10cm浮かせ、3秒かけてお尻が床に触れる手前まで下げ、手のひらで床を押して戻す（足で立ち上がらない）。12回×2セット（間に1分休む）。",
