    cues:{"do":"お尻をぎゅっと締めたまま、呼吸を続ける。","dont":"頭を後ろへだらんと落として、あごを上げない。"}, beginnerSafe:false, easyOption:"脚を伸ばしたままではお尻が持ち上がらなければ、両ひざを立て、かかとをお尻から手のひら2枚ぶん（約40cm）前の床に置く。手のひらと足の裏で床を押してお尻を上がるところまで上げ、10秒キープ→お尻を下ろして10秒休む、を3回で30秒ぶん。1分休んで2セット。",
