    cues:{"do":"手のひらと足の裏で床を押し続けて、お尻の高さを保つ。","dont":"頭を後ろへだらんと落として、あごを上げない。"}, easyOption:"30秒がもたなければ、10秒キープ→お尻を下ろして10秒休む、を3回くり返して30秒ぶんにする。これを3セット（間に1分休む）。",
